//! Legacy lifecycle controls for differential integration tests.
//! Kept behind `test-support` so the tests exercise the actual compiled library
//! without copying its private live-mode or reset implementation.

pub fn set_legacy_live_clock(lua: &mlua::Lua, live: bool) {
    if live {
        lua.set_app_data(crate::live::LiveMode(0));
    } else {
        lua.remove_app_data::<crate::live::LiveMode>();
    }
}

pub fn reset_legacy_clock(lua: &mlua::Lua) -> mlua::Result<()> {
    crate::runtime::reset_song_runtime_position(lua)
}

pub fn take_legacy_actor_sounds(lua: &mlua::Lua) -> Vec<crate::SongLuaActorSound> {
    crate::live::migration_take_actor_sounds(lua)
}
pub fn legacy_sound_capture(lua: &mlua::Lua, queued_startup: Option<bool>) {
    crate::lua_util::migration_sound_capture(lua, queued_startup);
}
pub fn take_legacy_prepared_sounds(lua: &mlua::Lua) -> Vec<crate::SongLuaSoundEvent> {
    crate::lua_util::take_runtime_sounds(lua)
}
pub fn take_legacy_sprite_textures(lua: &mlua::Lua) -> Vec<(usize, crate::SongLuaSpriteTexture)> {
    crate::lua_util::take_sprite_textures(lua)
}
pub fn legacy_multi_vertex_mesh(
    lua: &mlua::Lua,
    name: &str,
) -> Result<Option<super::ActorMesh>, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    let Some(vertices) = crate::lua_util::read_actor_multi_vertex_mesh(&actor)? else {
        return Ok(None);
    };
    let texture_path =
        crate::lua_util::live_multi_vertex_texture_path(&actor).map_err(|e| e.to_string())?;
    Ok(Some(super::ActorMesh {
        vertices,
        texture_path,
    }))
}
pub fn legacy_proxy_target(
    lua: &mlua::Lua,
    name: &str,
) -> Result<Option<crate::SongLuaProxyTarget>, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    crate::lua_util::read_proxy_target_kind(&actor)
}
pub fn take_legacy_judgment_textures(
    lua: &mlua::Lua,
) -> Vec<(usize, crate::SongLuaJudgmentTexture)> {
    crate::lua_util::take_judgment_textures(lua)
}
pub fn legacy_bitmap_text(lua: &mlua::Lua, name: &str) -> Result<super::BitmapText, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    let font = crate::lua_util::read_bitmap_font(&actor)?;
    let kind: String = actor
        .get("__songlua_actor_type")
        .map_err(|e| e.to_string())?;
    if let Some(text) = crate::input_status_actor_text(&kind) {
        return Ok(super::BitmapText {
            font,
            text: text.into(),
            stroke_color: None,
            attributes: std::sync::Arc::from([]),
        });
    }
    let value = actor.get("Text").map_err(|e| e.to_string())?;
    let text = crate::lua_util::lua_text_value(value)
        .map_err(|e| e.to_string())?
        .into();
    let stroke_color = crate::lua_util::read_actor_color_field(&actor, "__songlua_stroke_color")?
        .or_else(|| {
            crate::lua_util::read_actor_color_field(&actor, "StrokeColor")
                .ok()
                .flatten()
        });
    let attributes = crate::lua_util::read_bitmap_text_attributes(&actor)?;
    Ok(super::BitmapText {
        font,
        text,
        stroke_color,
        attributes,
    })
}

pub fn legacy_graph_display(
    lua: &mlua::Lua,
    name: &str,
    context: &crate::SongLuaCompileContext,
) -> Result<super::GraphDisplay, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    let state = crate::lua_util::actor_overlay_initial_state(&actor)?;
    Ok(super::GraphDisplay {
        size: crate::lua_util::read_graph_display_size(state, context),
        body_values: crate::lua_util::read_graph_display_values(&actor)?,
        body_state: crate::lua_util::read_graph_display_body_state(lua, &actor)?,
        line_state: crate::lua_util::read_graph_display_line_state(lua, &actor)?,
    })
}

pub fn legacy_song_meter_display(
    lua: &mlua::Lua,
    name: &str,
) -> Result<Option<super::SongMeterDisplay>, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    Ok(
        crate::lua_util::read_song_meter_display_state(lua, &actor)?.map(
            |(stream_width, stream_state)| super::SongMeterDisplay {
                stream_width,
                stream_state,
            },
        ),
    )
}

pub fn legacy_frame_texture(lua: &mlua::Lua, name: &str) -> Result<super::FrameTexture, String> {
    let actor: mlua::Table = lua.globals().get(name).map_err(|e| e.to_string())?;
    let kind: crate::SongLuaOverlayKind<(), (), ()> = crate::lua_util::read_aft_kind(&actor)?;
    let crate::SongLuaOverlayKind::ActorFrameTexture {
        capture_name,
        capture_size,
        alpha_buffer,
        depth_buffer,
        float_buffer,
    } = kind
    else {
        unreachable!()
    };
    Ok(super::FrameTexture {
        capture_name,
        capture_size,
        alpha_buffer,
        depth_buffer,
        float_buffer,
    })
}

/// Execute the actual production draw traversal, exposing capture errors before
/// the application wrapper reports them. Restore its callback flag on all exits.
pub fn draw_legacy_actor_scene(lua: &mlua::Lua, live: bool) -> mlua::Result<()> {
    let root: mlua::Table = lua.globals().get("root")?;
    let prior = lua
        .globals()
        .raw_get::<mlua::Value>("__songlua_draw_callback_active")?;
    lua.globals()
        .raw_set("__songlua_draw_callback_active", true)?;
    let result = if live {
        crate::draw_capture::run_live(lua, &root)
    } else {
        crate::draw_capture::run(lua, &root)
    };
    lua.globals()
        .raw_set("__songlua_draw_callback_active", prior)?;
    result
}

pub fn take_legacy_actor_draw_frames(
    lua: &mlua::Lua,
    sources: &[(&str, crate::SongLuaDrawSource)],
) -> Result<Vec<(usize, crate::SongLuaDrawFrame)>, String> {
    let mut bindings = rustc_hash::FxHashMap::default();
    for &(name, source) in sources {
        let actor: mlua::Table = lua.globals().get(name).map_err(|error| error.to_string())?;
        bindings.insert(actor.to_pointer() as usize, source);
    }
    let Some(capture) = lua.remove_app_data::<crate::draw_commands::Capture>() else {
        return Ok(Vec::new());
    };
