#[derive(Debug, PartialEq)]
enum Observation {
    Nil,
    Boolean(bool),
    Number(f64),
    Bytes(Vec<u8>),
}

// Run the same declaration and probe through the actual production constructor
// and the Rust adapter. Assertions inside probes must pass on both engines;
// the returned observations also catch otherwise unnoticed ordering changes.
fn compare_scene(definition: &str, probe: &str) {
    let legacy = deadsync_song_lua::rust_engine::test_support::legacy_actor_scene(definition)
        .expect("production actor construction");
    let expected: mlua::MultiValue = legacy.load(probe).eval().expect("production actor probe");
    let expected: Vec<_> = expected
        .into_iter()
        .map(|value| match value {
            mlua::Value::Nil => Observation::Nil,
            mlua::Value::Boolean(value) => Observation::Boolean(value),
            mlua::Value::Integer(value) => Observation::Number(value as f64),
            mlua::Value::Number(value) => Observation::Number(value),
            mlua::Value::String(value) => Observation::Bytes(value.as_bytes().to_vec()),
            other => panic!("non-scalar production observation: {other:?}"),
        })
        .collect();
    let mut rust = runtime();
    instantiate(&mut rust, definition);
    let actual: Vec<_> = execute(&mut rust, probe)
        .into_iter()
        .map(|value| match value {
            Value::Nil => Observation::Nil,
            Value::Boolean(value) => Observation::Boolean(value),
            Value::Number(value) => Observation::Number(value),
            Value::String(value) => {
                Observation::Bytes(rust.vm_mut().string_bytes(value).unwrap().to_vec())
            }
            other => panic!("non-scalar Rust observation: {other:?}"),
        })
        .collect();
    assert_eq!(actual.len(), expected.len());
    for (index, (actual, expected)) in actual.iter().zip(&expected).enumerate() {
        match (actual, expected) {
            (Observation::Bytes(actual), Observation::Bytes(expected)) => {
                let actual: Vec<_> = actual.split(|byte| *byte == b'|').collect();
                let expected: Vec<_> = expected.split(|byte| *byte == b'|').collect();
                assert_eq!(
                    actual.len(),
                    expected.len(),
                    "observation {index} record count"
                );
                for (record, (actual, expected)) in actual.iter().zip(&expected).enumerate() {
                    assert_eq!(
                        String::from_utf8_lossy(actual),
                        String::from_utf8_lossy(expected),
                        "observation {index}, record {record}"
                    );
                }
            }
            _ => assert_eq!(actual, expected, "observation {index}"),
        }
    }
}

enum Phase<'a> {
    Start,
    Advance(f64),
    Script(&'a str),
}

fn compare_lifecycle(definition: &str, phases: &[Phase<'_>]) {
    use deadsync_song_lua::rust_engine::test_support::{
        advance_legacy_actor_scene, legacy_actor_scene, start_legacy_actor_scene,
    };
    let source = format!(
        r#"
        events={{}}
        function log(...) for i=1,select('#',...) do
            local value=select(i,...)
            events[#events+1]=type(value)=='number' and string.format('%.17g',value) or tostring(value)
        end end
        function observe()
            local result={{table.concat(events,':')}}
            local function visit(a)
                result[#result+1]=a:GetName()
                for _,v in ipairs{{a:GetX(),a:GetY(),a:GetZ(),a:GetDestX(),a:GetDestY(),a:GetDestZ(),
                    a:GetZoomX(),a:GetZoomY(),a:GetRotationZ(),a:getaux(),a:GetTweenTimeLeft()}} do
                    result[#result+1]=v~=v and 'nan' or string.format('%.17g',v)
                end
                for i=1,#a do visit(a[i]) end
            end
            visit(root)
            return table.concat(result,'|')
        end
        {definition}
    "#
    );
    let legacy = legacy_actor_scene(&source).unwrap();
    let mut rust = runtime();
    let scene = instantiate(&mut rust, &source);
    let mut seconds = 0.0;
    for (index, phase) in phases.iter().enumerate() {
        match phase {
            Phase::Start => {
                start_legacy_actor_scene(&legacy).unwrap();
                assert!(rust.start_actor_scene(scene).unwrap());
            }
            Phase::Advance(delta) => {
                seconds += delta;
                advance_legacy_actor_scene(&legacy, seconds, *delta).unwrap();
                assert!(rust.advance_actor_scene(scene, *delta).unwrap());
            }
            Phase::Script(source) => {
                legacy.load(*source).exec().unwrap();
                execute(&mut rust, source);
            }
        }
        let expected: String = legacy.load("return observe()").eval().unwrap();
        let Value::String(actual) = execute(&mut rust, "return observe()")[0] else {
            panic!("expected observation string");
        };
        let actual = std::str::from_utf8(rust.vm_mut().string_bytes(actual).unwrap()).unwrap();
        assert_eq!(actual, expected, "lifecycle phase {index}");
    }
}

