            observe(self,p); self:GetParent():name('temporary'); self:draworder(-1)
        end}
        definition=Def.ActorFrame{Name='root', InitCommand=observe,
            Def.Quad{Name='first', InitCommand=observe},shared,shared,
            Def.Actor{Condition=false,InitCommand=function()error('excluded')end}}
        return definition
    "#).unwrap();
    let values: mlua::MultiValue = lua
        .load(
            r#"
        local group=root:GetChild('same')
        return table.concat(seen,'|'),root.Class,root.Name,root.InitCommand==definition.InitCommand,
            type(getmetatable(root)), group[1].ctx==nil, group[1]==group[2]
    "#,
        )
        .eval()
        .unwrap();
    assert_eq!(
        values[0],
        mlua::Value::String(
            lua.create_string("first::3|same::3|same:temporary:3|root:-:3")
                .unwrap()
        )
    );
    assert_eq!(
        values[1],
        mlua::Value::String(lua.create_string("ActorFrame").unwrap())
    );
    assert_eq!(
        values[2],
        mlua::Value::String(lua.create_string("root").unwrap())
    );
    assert_eq!(values[3], mlua::Value::Boolean(true));
    assert_eq!(
        values[4],
        mlua::Value::String(lua.create_string("table").unwrap())
    );
    assert_eq!(values[5], mlua::Value::Boolean(true));
    assert_eq!(values[6], mlua::Value::Boolean(false));
    assert_eq!(values.len(), 7);
}

